ALTER TABLE delivery_settings ADD COLUMN not_before INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS provider_quota(id INTEGER PRIMARY KEY CHECK(id=1),cycle_start INTEGER NOT NULL,cycle_end INTEGER NOT NULL,used INTEGER NOT NULL,remaining INTEGER NOT NULL,allowance INTEGER NOT NULL,checked_at INTEGER NOT NULL,error_code TEXT,external_used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ops_reports(source TEXT PRIMARY KEY,state TEXT NOT NULL,checked_at INTEGER NOT NULL,detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ops_backups(source TEXT NOT NULL,day TEXT NOT NULL,created_at INTEGER NOT NULL,sha256 TEXT NOT NULL,format TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(source,day));
